package com.bare.messagescalls.dash;
import android.content.Intent; import android.os.Bundle; import android.view.Menu; import android.view.MenuItem; import androidx.annotation.Nullable; import androidx.appcompat.app.AppCompatActivity; import androidx.appcompat.widget.Toolbar; import com.bare.R; import com.bare.messagescalls.backups.MessagesBackupsActivity; import com.bare.messagescalls.conversationsview.ConversationsActivity; import com.bare.settings.SettingsActivity; import com.bare.settings.SettingsDetailActivity; import com.google.android.material.dialog.MaterialAlertDialogBuilder;
public final class MessagesDashActivity extends AppCompatActivity{
 protected void onCreate(@Nullable Bundle s){super.onCreate(s);setContentView(R.layout.smscalls_dash_activity);Toolbar t=findViewById(R.id.toolbar);t.setTitle(R.string.messages);setSupportActionBar(t);if(getSupportActionBar()!=null)getSupportActionBar().setDisplayHomeAsUpEnabled(true);findViewById(R.id.btn_create_backup).setOnClickListener(v->boundary(R.string.messages_backup));findViewById(R.id.tv_local_state).setOnClickListener(v->startActivity(new Intent(this,MessagesBackupsActivity.class)));}
 public boolean onCreateOptionsMenu(Menu m){getMenuInflater().inflate(R.menu.menu_sms_dash,m);m.findItem(R.id.action_view_messages).setVisible(true);return true;}
 public boolean onOptionsItemSelected(MenuItem i){if(i.getItemId()==R.id.action_sms_settings){Intent x=new Intent(this,SettingsDetailActivity.class);x.putExtra("category",2);x.putExtra("category_title",getString(R.string.messages_backups));startActivity(x);return true;}if(i.getItemId()==R.id.action_view_messages){startActivity(new Intent(this,ConversationsActivity.class));return true;}if(i.getItemId()==R.id.action_settings){startActivity(new Intent(this,SettingsActivity.class));return true;}return super.onOptionsItemSelected(i);}
 void boundary(int title){new MaterialAlertDialogBuilder(this).setTitle(title).setMessage(R.string.p3_activity_boundary).setPositiveButton(R.string.close,null).show();}
 public boolean onSupportNavigateUp(){setResult(RESULT_CANCELED);finish();return true;}
}